module.exports="\",\"border\":\"data:image/png;base64,\",\"interior\":null}];\nconst APPROVED_FEATHER_PX=2;\nconst approvedImgCache=new Map();\nconst approvedRasterCache=new Map();\nfunction approvedImage(src){\n if(approvedImgCache.has(src))return approvedImgCache.get(src);\n const result=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src});\n approvedImgCache.set(src,result);return result;\n}\nasync function approvedRaster(idx){\n if(approvedRasterCache.has(idx))return approvedRasterCache.get(idx);\n const item=APPROVED_LOGO_ASSETS[idx];\n const output=(async()=>{\n  const [photo,border,interior]=await Promise.all([approvedImage(item.image),approvedImage(item.border),item.interior?approvedImage(item.interior):Promise.resolve(null)]);\n  const width=photo.width,height=photo.height;\n  const cv=document.createElement('canvas');cv.width=width;cv.height=height;\n  const cx=cv.getContext('2d',{willReadFrequently:true});cx.drawImage(photo,0,0,width,height);const p=cx.getImageData(0,0,width,height).data;\n  function getMask(im){\n   // Original vectors remain stationary. Feather the grayscale coverage values,\n   // not the opaque mask image itself, to obtain a true soft color transition.\n   const m=document.createElement('canvas');m.width=width;m.height=height;\n   const x=m.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0,width,height);\n   const data=x.getImageData(0,0,width,height).data;\n   const source=new Float32Array(width*height);\n   for(let i=0;i<source.length;i++) source[i]=data[i*4];\n   const radius=Math.ceil(APPROVED_FEATHER_PX*3),sigma=APPROVED_FEATHER_PX;\n   const kernel=new Float32Array(2*radius+1);let total=0;\n   for(let k=-radius;k<=radius;k++){const v=Math.exp(-.5*(k/sigma)**2);kernel[k+radius]=v;total+=v}\n   for(let i=0;i<kernel.length;i++)kernel[i]/=total;\n   const horizontal=new Float32Array(source.length),out=new Uint8Array(source.length);\n   for(let y=0;y<height;y++)for(let xx=0;xx<width;xx++){\n     let value=0;for(let k=-radius;k<=radius;k++)value+=source[y*width+Math.max(0,Math.min(width-1,xx+k))]*kernel[k+radius];\n     horizontal[y*width+xx]=value;\n   }\n   for(let y=0;y<height;y++)for(let xx=0;xx<width;xx++){\n     let value=0;for(let k=-radius;k<=radius;k++)value+=horizontal[Math.max(0,Math.min(height-1,y+k))*width+xx]*kernel[k+radius];\n     out[y*width+xx]=Math.round(value);\n   }\n   return out;\n  }\n  return {width,height,photo:p,border:getMask(border),interior:interior?getMask(interior):new Uint8Array(width*height)};\n })();approvedRasterCache.set(idx,output);return output;\n}\nfunction approvedColor(h){if(!/^#[0-9a-f]{6}$/i.test(h||''))h='#808080';return [1,3,5].map(i=>parseInt(h.slice(i,i+2),16))}\nlet approvedRenderSerial=0;\nasync function approvedDrawLogoCard(canvas,asset,colors){\n const ticket=++approvedRenderSerial;canvas.dataset.renderTicket=ticket;\n try{\n const r=await approvedRaster(asset),w=r.width,h=r.height;\n if(+canvas.dataset.renderTicket!==ticket||!canvas.isConnected)return;\n canvas.width=w;canvas.height=h;const cx=canvas.getContext('2d',{willReadFrequently:true});const out=cx.createImageData(w,h);\n const fabric=approvedColor(colors.fabric),interior=approvedColor(colors.interior),border=approvedColor(colors.border);\n const v=out.data;\n for(let j=0;j<w*h;j++){\n  const k=j*4,gray=(r.photo[k]+r.photo[k+1]+r.photo[k+2])/765;\n  const b=r.border[j]/255,inner=r.interior[j]/255;\n  const bg=Math.max(0,1-Math.max(b,inner));\n  const norm=bg+inner+b||1;\n  const l=gray-.5;\n  for(let ch=0;ch<3;ch++){\n   const mapped=(fabric[ch]*bg+interior[ch]*inner+border[ch]*b)/norm;\n   const shade=Math.max(.64,Math.min(1.36,1+l*.66));\n   v[k+ch]=Math.max(0,Math.min(255,mapped*shade));\n  }\n  v[k+3]=255;\n }\n cx.putImageData(out,0,0);\n }catch(err){console.warn('Logo preview failed',err)}\n}\nfunction approvedPanelColors(id){\n const shirt=state.kit.colors,short=state.short.colors;\n switch(id){\n case 'chestKappa':return {fabric:shirt.secondary,interior:shirt.kappa,border:shirt.kappa};\n case 'sleeveKappa':return {fabric:shirt.shoulders,interior:shirt.kappaSide||shirt.kappa,border:shirt.kappaSide||shirt.kappa};\n case 'shortKappa':return {fabric:short.dominant,interior:short.kappa,border:short.kappa};\n case 'shirtShield':return {fabric:shirt.dominant,interior:shirt.shield,border:shirt.leopard};\n case 'shortShield':return {fabric:short.dominant,interior:short.shield,border:short.leopard};\n }\n}\nconst approvedCards=[['chestKappa','Brand Logo · Chest','Chest panel',4],['sleeveKappa','Brand Logo · Sleeves','Shoulder panel',4],['shortKappa','Brand Logo · Short','Short dominant',4],['shirtShield','Club Logo · Shirt','Shirt dominant',0],['shortShield','Club Logo · Shorts','Short dominant',0]];\nlet approvedShieldMaterial=0;\nfunction approvedLogoZone(){\n let root=document.getElementById('approvedLogoZone');if(root)return root;\n const anchor=document.getElementById('kitFields');if(!anchor)return null;\n root=document.createElement('div');root.id='approvedLogoZone';root.className='approved-logo-zone';\n root.innerHTML='<h3>Logo Materials · Live Panel Colors</h3><p>Previews follow the colors in the shirt and shorts editor automatically. Feather fixed at 2px.</p>';\n const choice=document.createElement('select');choice.className='approved-logo-select';choice.setAttribute('aria-label','Club logo material');\n APPROVED_LOGO_ASSETS.slice(0,4).forEach((a,i)=>{const op=document.createElement('option');op.value=i;op.textContent=a.name;choice.appendChild(op)});\n choice.onchange=()=>{approvedShieldMaterial=+choice.value;globalLogoMaterial=approvedShieldMaterial;approvedRefreshLogos();for(const w of ['kit','short'])draw(w)};root.append(choice);\n const grid=document.createElement('div');grid.className='approved-logo-grid';\n for(const [id,title,reference] of approvedCards){const card=document.createElement('div');card.className='approved-logo-card';card.innerHTML='<strong></strong><canvas></canvas><em></em>';card.querySelector('strong').textContent=title;card.querySelector('em').textContent='Background: '+reference;card.dataset.logoId=id;grid.appendChild(card)}\n root.append(grid);anchor.parentNode.insertBefore(root,anchor);return root;\n}\nfunction approvedRefreshLogos(){const root=approvedLogoZone();if(!root)return;\n for(const [id,, ,asset] of approvedCards){const c=root.querySelector('[data-logo-id=\"'+id+'\"] canvas');\n const index=asset===4?4:approvedShieldMaterial;\n approvedDrawLogoCard(c,index,approvedPanelColors(id));}\n}\n/* Always visible fabric micro preview; full original preview remains clickable. */\nfunction approvedMiniFabric(which,section){\n let holder=section.querySelector('.approved-fabric-quick');if(!holder){holder=document.createElement('div');holder.className='approved-fabric-quick';holder.innerHTML='<canvas width=\"160\" height=\"130\" title=\"Enlarge fabric preview\"></canvas><div><small></small><div><small>Tap image to enlarge</small></div></div>';section.append(holder);\n holder.querySelector('canvas').onclick=()=>v55OpenFabric(which,section.dataset.panel||'dominant');}\n const n=Math.min(3,Math.max(1,state[which].fabric||1));holder.querySelector('small').textContent='Fabric '+n+' · Live preview';\n const cv=holder.querySelector('canvas');let im=v55GetImage(V55_FABRIC_SAMPLES[n-1]);\n const repaint=()=>{if(!im.naturalWidth)return;const c=cv.getContext('2d',{willReadFrequently:true});c.drawImage(im,0,0,160,130);\n const imaged=c.getImageData(0,0,160,130);const pix=imaged.data;const rgb=approvedColor(state[which].colors[section.dataset.panel]||state[which].colors.dominant);\n const profile=v88ColorProfile(state[which].colors[section.dataset.panel]||state[which].colors.dominant);\n for(let i=0;i<pix.length;i+=4){const g=(pix[i]+pix[i+1]+pix[i+2])/3;const shade=Math.max(.58,Math.min(1.46,1+(g-140)/180));for(let k=0;k<3;k++)pix[i+k]=profile==='mid'?Math.max(0,Math.min(255,rgb[k]*shade)):v88RenderedChannel(rgb[k],g,profile);pix[i+3]=255;}c.putImageData(imaged,0,0);};\n if(im.complete&&im.naturalWidth)repaint();else im.addEventListener('load',repaint,{once:true});\n}\n/* Hook the original controls/draw without removing any existing export functionality. */\nconst approvedOldFabricControl=fabricControl;\nfabricControl=function(which,key='dominant'){const node=approvedOldFabricControl(which,key);approvedMiniFabric(which,node);return node};\nconst approvedOldDraw=draw;\ndraw=function(which){approvedOldDraw(which);document.querySelectorAll('.fabric-picker').forEach(s=>{const w=s.closest('#kitFields')?'kit':s.closest('#shortFields')?'short':which;approvedMiniFabric(w,s)})};\n\n/* V75: Integrated logo controls, one relevant preview, click to enlarge. */\nlet approvedInlineSelected=null;\nfunction approvedLogoTarget(which,key){\n if(which==='kit'){\n  if(key==='kappa')return 'chestKappa';\n  if(key==='kappaSide')return 'sleeveKappa';\n  if(key==='shield'||key==='leopard')return 'shirtShield';\n }else{\n  if(key==='kappa')return 'shortKappa';\n  if(key==='shield'||key==='leopard')return 'shortShield';\n }\n return 'shirtShield';\n}\nconst approvedLocations=[\n ['chestKappa','Kappa Chest','kit','kappa'],\n ['sleeveKappa','Brand Logo · Sleeves','kit','kappaSide'],\n ['shortKappa','Brand Logo · Short','short','kappa'],\n ['shirtShield','Club Logo · Shirt','kit','shield'],\n ['shortShield','Club Logo · Short','short','shield']\n];\nfunction approvedPickLocation(which,key){\n openColorFromArtwork(which,key);\n}\nfunction approvedShowLarge(asset,colors,label){\n let modal=document.querySelector('#approvedLogoLightbox');\n if(!modal){\n  modal=document.createElement('div');modal.id='approvedLogoLightbox';modal.className='v55-fabric-modal';\n  modal.innerHTML='<div class=\"v55-fabric-dialog\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Logo material enlarged\"><button type=\"button\" class=\"v55-close\" aria-label=\"Close\">×</button><strong></strong><canvas></canvas></div>';\n  document.body.append(modal);\n  modal.querySelector('.v55-close').onclick=()=>modal.classList.remove('open');\n  modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};\n }\n modal.querySelector('strong').textContent=label;\n modal.classList.add('open');\n approvedDrawLogoCard(modal.querySelector('canvas'),asset,colors);\n}\nfunction approvedInlineLogoControl(which,key){\n const target=approvedLogoTarget(which,key);\n const club=target==='shirtShield'||target==='shortShield';\n const wrap=document.createElement('div');wrap.className='v75-logo-inline';\n const title=document.createElement('strong');title.textContent=club?'Club Logo Material':'Brand Logo Material';wrap.append(title);\n const locations=document.createElement('div');locations.className='v75-logo-tabs';\n for(const [id,caption,w,k] of approvedLocations){\n  const b=document.createElement('button');b.type='button';b.textContent=caption;\n  b.className=id===target?'active':'';\n  b.onclick=()=>approvedPickLocation(w,k);\n  locations.append(b);\n }\n wrap.append(locations);\n const selector=document.createElement('div');selector.className='v75-logo-step';\n if(club){\n  const prev=document.createElement('button');prev.type='button';prev.textContent='‹';prev.title='Previous material';\n  prev.onclick=()=>{approvedShieldMaterial=(approvedShieldMaterial+3)%4;globalLogoMaterial=approvedShieldMaterial;controls(which)};\n  const label=document.createElement('span');label.textContent=APPROVED_LOGO_ASSETS[approvedShieldMaterial].name;\n  const next=document.createElement('button');next.type='button';next.textContent='›';next.title='Next material';\n  next.onclick=()=>{approvedShieldMaterial=(approvedShieldMaterial+1)%4;globalLogoMaterial=approvedShieldMaterial;controls(which)};\n  selector.append(prev,label,next);\n }else{const label=document.createElement('span');label.textContent='Heat Transfer – Kappa';selector.append(label)}\n wrap.append(selector);\n const thumb=document.createElement('canvas');thumb.className='v75-logo-canvas';thumb.title='Tap to enlarge';thumb.setAttribute('role','button');thumb.tabIndex=0;\n const asset=club?approvedShieldMaterial:4;\n const colors=approvedPanelColors(target);\n const open=()=>approvedShowLarge(asset,approvedPanelColors(target),(club?'Club Logo':'Brand Logo')+' · '+(target.replace(/([A-Z])/g,' $1')));\n thumb.onclick=open;thumb.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}};\n wrap.append(thumb);\n const hint=document.createElement('small');hint.textContent='Live panel colors · Tap preview to enlarge · Feather 2px';wrap.append(hint);\n Promise.resolve().then(()=>approvedDrawLogoCard(thumb,asset,colors));\n return wrap;\n}\n</script>\n<script>window.addEventListener(\"load\",()=>{if(typeof addShortCompletionControl===\"function\")addShortCompletionControl();});</script><script id=\"v85-transform-script\">\n(function(){\n function mount(){\n  for(const which of ['kit','short']){\n   const canvas=document.getElementById(which+'Canvas');if(!canvas)continue;\n   const card=canvas.closest('.previewcard');if(!card||card.querySelector('.v85-transform'))continue;\n   const bar=document.createElement('div');bar.className='v85-transform';bar.innerHTML='<button type=\"button\" class=\"v85-close\" aria-label=\"Close transform\">×</button><div class=\"v85-head\">SUBLIMATION</div><div class=\"v85-areas\"><div class=\"v85-pad\" data-op=\"move\" role=\"button\" aria-label=\"Drag to move\"><span>✥</span><small>MOVE</small></div><div class=\"v85-pad\" data-op=\"scale\" role=\"button\" aria-label=\"Drag up to enlarge, down to shrink\"><span>↕</span><small>SCALE</small></div></div><div class=\"v85-status\">Scale 0 / 10</div><div class=\"v85-tip\">Drag with one finger</div>';\n   card.append(bar);\n   bar.addEventListener('pointerdown',e=>e.stopPropagation());bar.addEventListener('click',e=>e.stopPropagation());\n   bar.querySelector('.v85-close').addEventListener('click',()=>{activeSublimationMove=null;bar.classList.remove('on');controls(which)});\n   for(const pad of bar.querySelectorAll('.v85-pad')){\n    let drag=null;\n    pad.addEventListener('pointerdown',e=>{\n     const a=activeSublimationMove;if(!a||a.which!==which)return;\n     const p=patternState(which,a.key);if(!resolvedPattern(which,a.key).id)return;\n     const rect=canvas.getBoundingClientRect();\n     drag={id:e.pointerId,x:e.clientX,y:e.clientY,px:p.x||0,py:p.y||0,size:Number(p.size)||0,sx:canvas.width/rect.width,sy:canvas.height/rect.height};\n     pad.setPointerCapture(e.pointerId);e.preventDefault();e.stopPropagation();\n    });\n    pad.addEventListener('pointermove',e=>{\n     if(!drag||drag.id!==e.pointerId||!activeSublimationMove)return;\n     const a=activeSublimationMove,p=patternState(which,a.key);p.match='';\n     if(pad.dataset.op==='move'){\n       p.x=Math.round(drag.px+(e.clientX-drag.x)*drag.sx);p.y=Math.round(drag.py+(e.clientY-drag.y)*drag.sy);\n     }else{\n       p.size=Math.max(0,Math.min(10,Math.round((drag.size+(drag.y-e.clientY)/18)*10)/10));\n     }\n     draw(which);bar.querySelector('.v85-status').textContent='Scale '+Math.round(p.size*10)/10+' / 10';e.preventDefault();\n    });\n    function finish(e){if(drag&&drag.id===e.pointerId){drag=null;controls(which);sync()}}\n    pad.addEventListener('pointerup',finish);pad.addEventListener('pointercancel',finish);\n   }\n  }\n  sync();\n }\n function sync(){\n  for(const which of ['kit','short']){\n   const c=document.getElementById(which+'Canvas'),bar=c&&c.closest('.previewcard')?.querySelector('.v85-transform');if(!bar)continue;\n   const a=activeSublimationMove;const visible=!!(a&&a.which===which&&resolvedPattern(which,a.key).id);\n   bar.classList.toggle('on',visible);\n   if(visible){const p=patternState(which,a.key);bar.querySelector('.v85-status').textContent='Scale '+(Math.round((p.size||0)*10)/10)+' / 10';}\n  }\n }\n if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();\n // Keep controls synchronized when a panel selection or ON/OFF toggle changes.\n document.addEventListener('click',()=>requestAnimationFrame(sync),true);\n window.addEventListener('resize',sync);\n})();\n</script><style id=\"v86-transform-css\">\n.v85-transform .v85-pad{cursor:pointer;touch-action:manipulation;transition:background .12s,border-color .12s,color .12s}\n.v85-transform .v85-pad.v86-selected{background:#1479db!important;color:#fff!important;border-color:#0863bf!important;box-shadow:0 0 0 2px rgba(20,121,219,.18)}\n.v85-transform .v85-pad.v86-selected small{color:#fff}\n.v85-transform .v85-tip{font-size:9px}\n.preview.v86-editing{touch-action:none!important;cursor:crosshair}\n.preview.v86-editing canvas{touch-action:none!important}\n</style><script id=\"v86-transform-script\">\n(function(){\n let activeId='',selected='move',drag=null;\n const whiches=['kit','short'];\n function currentId(){let a=activeSublimationMove;return a&&resolvedPattern(a.which,a.key).id ? a.which+'|'+a.key : '';}\n function updateUI(){\n  const next=currentId();if(next!==activeId){activeId=next;selected='move';drag=null;}\n  for(const which of whiches){\n   const canvas=document.getElementById(which+'Canvas');if(!canvas)continue;\n   const preview=canvas.closest('.preview'),bar=canvas.closest('.previewcard')?.querySelector('.v85-transform');\n   if(!bar)continue;\n   let active=!!(activeId&&activeSublimationMove?.which===which);\n   bar.classList.toggle('on',active);preview?.classList.toggle('v86-editing',active);\n   for(const pad of bar.querySelectorAll('.v85-pad')){\n    const chosen=active&&pad.dataset.op===selected;\n    pad.classList.toggle('v86-selected',chosen);\n    pad.setAttribute('aria-pressed',String(chosen));\n   }\n   const tip=bar.querySelector('.v85-tip');if(tip)tip.textContent=selected==='move'?'Drag on kit to move · repeat anytime':'Swipe up/down on kit to scale · repeat anytime';\n   if(active){const p=patternState(which,activeSublimationMove.key);const status=bar.querySelector('.v85-status');if(status)status.textContent='Scale '+Math.round((Number(p.size)||0)*10)/10+' / 10';}\n  }\n }\n function install(){\n  for(const which of whiches){\n   const canvas=document.getElementById(which+'Canvas');if(!canvas)continue;\n   const preview=canvas.closest('.preview'),bar=canvas.closest('.previewcard')?.querySelector('.v85-transform');\n   if(!preview||!bar||bar.dataset.v86)return;bar.dataset.v86='yes';\n   // Replace legacy pads to remove V85's press-and-drag handlers.\n   for(const old of [...bar.querySelectorAll('.v85-pad')]){\n    const pad=old.cloneNode(true);old.replaceWith(pad);pad.tabIndex=0;\n    pad.setAttribute('role','button');\n    const select=e=>{e.preventDefault();e.stopPropagation();if(!currentId()||activeSublimationMove.which!==which)return;selected=pad.dataset.op;drag=null;updateUI();};\n    pad.addEventListener('click',select);\n    pad.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){select(e);}});\n   }\n   // Preview handles the edit gesture; mode remains selected after release.\n   preview.addEventListener('pointerdown',e=>{\n    const a=activeSublimationMove;if(!a||a.which!==which||!currentId())return;\n    if(e.button!==undefined&&e.button!==0)return;\n    const p=patternState(which,a.key),rect=canvas.getBoundingClientRect();\n    if(!rect.width||!rect.height)return;\n    drag={which,key:a.key,id:e.pointerId,startX:e.clientX,startY:e.clientY,x:Number(p.x)||0,y:Number(p.y)||0,size:Number(p.size)||0,dx:canvas.width/rect.width,dy:canvas.height/rect.height,mode:selected};\n    try{preview.setPointerCapture(e.pointerId)}catch(err){}\n    e.preventDefault();e.stopImmediatePropagation();\n   },true);\n   preview.addEventListener('pointermove',e=>{\n    if(!drag||drag.which!==which||drag.id!==e.pointerId)return;\n    const a=activeSublimationMove;if(!a||a.which!==which||a.key!==drag.key){drag=null;return;}\n    const p=patternState(which,a.key);p.match='';\n    if(drag.mode==='move'){\n     p.x=Math.max(-250,Math.min(250,Math.round(drag.x+(e.clientX-drag.startX)*drag.dx)));\n     p.y=Math.max(-250,Math.min(250,Math.round(drag.y+(e.clientY-drag.startY)*drag.dy)));\n    }else{\n     p.size=Math.max(0,Math.min(10,Math.round((drag.size+(drag.startY-e.clientY)/18)*10)/10));\n    }\n    draw(which);\n    const status=bar.querySelector('.v85-status');if(status)status.textContent='Scale '+p.size+' / 10';\n    e.preventDefault();e.stopImmediatePropagation();\n   },true);\n   const end=e=>{\n    if(!drag||drag.id!==e.pointerId||drag.which!==which)return;\n    drag=null;try{preview.releasePointerCapture(e.pointerId)}catch(err){}\n    // Do not reset selected mode or turn Move Sublimation OFF on finger lift.\n    e.preventDefault();e.stopImmediatePropagation();\n   };\n   preview.addEventListener('pointerup',end,true);preview.addEventListener('pointercancel',end,true);\n  }\n  updateUI();\n }\n if(document.readyState==='complete')install();else window.addEventListener('load',install,{once:true});\n document.addEventListener('click',()=>requestAnimationFrame(updateUI));\n})();\n</script><div style=\"position:fixed;bottom:7px;left:7px;z-index:9999;font:600 10px system-ui;background:#fffce8;color:#73550c;border:1px solid #d9c983;border-radius:5px;padding:3px 7px;pointer-events:none\">V1 · UNDER TESTING</div><script>\n(function(){\n let audience='Players';\n function clean(v){return String(v||'Untitled').trim().replace(/[^\\p{L}\\p{N} _-]+/gu,'').replace(/\\s+/g,'_').slice(0,72)||'Untitled'}\n window.v92ExportFilename=()=>['Training',audience,clean(document.getElementById('v93TeamName')?.value),clean(document.getElementById('v92DesignName')?.value)].join('_')+'.png';\n document.querySelectorAll('.v92-audience button').forEach(b=>b.addEventListener('click',()=>{audience=b.dataset.audience;document.querySelectorAll('.v92-audience button').forEach(x=>x.classList.toggle('active',x===b));}));\n})();\n</script><script id=\"v94-theme-script\">(function(){const KEY='kitlab-theme-v1';const read=()=>{try{return sessionStorage.getItem(KEY)||'light'}catch{return 'light'}};function apply(t){t=t==='dark'?'dark':'light';document.documentElement.dataset.theme=t;document.querySelectorAll('[data-theme-choice]').forEach(b=>{const yes=b.dataset.themeChoice===t;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes))});try{sessionStorage.setItem(KEY,t)}catch{}}document.addEventListener('click',e=>{const b=e.target.closest('[data-theme-choice]');if(b)apply(b.dataset.themeChoice)});apply(read());})();</script></body></html>";